     1	/**
     2	 * AWS Signature Version 4 on node:crypto (no dependency). Signs one request and returns the headers to add.
     3	 * Reference: https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_sigv-create-signed-request.html
     4	 *
     5	 * Only `host`, `content-type`, `x-amz-date` and `x-amz-security-token` are signed, so the caller may add other headers
     6	 * (request ids, tracing) afterwards without invalidating the signature. The canonical path is the path as sent with
     7	 * each segment encoded once more, which is the rule for every service except S3.
     8	 */
     9	import { createHash, createHmac } from "node:crypto";
    10	
    11	export interface AwsCredentials {
    12	  accessKeyId: string;
    13	  secretAccessKey: string;
    14	  sessionToken?: string;
    15	}
    16	
    17	export interface SigV4Input {
    18	  method: string;
    19	  url: string;
    20	  /** Headers to sign besides host and x-amz-*; only content-type is used. */
    21	  headers?: Record<string, string>;
    22	  body: string | Uint8Array;
    23	  region: string;
    24	  service: string;
    25	  credentials: AwsCredentials;
    26	  now: Date;
    27	}
    28	
    29	const sha256Hex = (data: string | Uint8Array): string => createHash("sha256").update(data).digest("hex");
    30	const hmac = (key: string | Buffer, data: string): Buffer => createHmac("sha256", key).update(data, "utf8").digest();
    31	
    32	/** RFC 3986 unreserved characters stay; everything else is percent-encoded as UTF-8 with upper-case hex. */
    33	export function uriEncode(value: string): string {
    34	  return encodeURIComponent(value).replace(/[!'()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
    35	}
    36	
    37	/** `YYYYMMDD'T'HHMMSS'Z'` */
    38	export function amzDate(now: Date): string {
    39	  return now.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
    40	}
    41	
    42	export function signingKey(secret: string, dateStamp: string, region: string, service: string): Buffer {
    43	  return hmac(hmac(hmac(hmac(`AWS4${secret}`, dateStamp), region), service), "aws4_request");
    44	}
    45	
    46	function canonicalQuery(params: URLSearchParams): string {
    47	  const pairs = [...params.entries()].map(([k, v]) => [uriEncode(k), uriEncode(v)] as const);
    48	  pairs.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));
    49	  return pairs.map(([k, v]) => `${k}=${v}`).join("&");
    50	}
    51	
    52	function canonicalPath(pathname: string): string {
    53	  return pathname.split("/").map((seg) => (seg === "" ? "" : uriEncode(seg))).join("/") || "/";
    54	}
    55	
    56	export interface SigV4Result {
    57	  /** Headers to send in addition to the caller's own (host is implied by the URL). */
    58	  headers: Record<string, string>;
    59	  canonicalRequest: string;
    60	  stringToSign: string;
    61	  signature: string;
    62	}
    63	
    64	export function signSigV4(input: SigV4Input): SigV4Result {
    65	  const url = new URL(input.url);
    66	  const date = amzDate(input.now);
    67	  const dateStamp = date.slice(0, 8);
    68	  const signed: Record<string, string> = { host: url.host, "x-amz-date": date };
    69	  const contentType = Object.entries(input.headers ?? {}).find(([k]) => k.toLowerCase() === "content-type")?.[1];
    70	  if (contentType !== undefined) signed["content-type"] = contentType.trim();
    71	  if (input.credentials.sessionToken) signed["x-amz-security-token"] = input.credentials.sessionToken;
    72	  const names = Object.keys(signed).sort();
    73	  const canonicalHeaders = names.map((n) => `${n}:${signed[n].replace(/\s+/g, " ")}\n`).join("");
    74	  const signedHeaders = names.join(";");
    75	  const canonicalRequest = [
    76	    input.method.toUpperCase(),
    77	    canonicalPath(url.pathname),
    78	    canonicalQuery(url.searchParams),
    79	    canonicalHeaders,
    80	    signedHeaders,
    81	    sha256Hex(input.body),
    82	  ].join("\n");
    83	  const scope = `${dateStamp}/${input.region}/${input.service}/aws4_request`;
    84	  const stringToSign = ["AWS4-HMAC-SHA256", date, scope, sha256Hex(canonicalRequest)].join("\n");
    85	  const signature = createHmac("sha256", signingKey(input.credentials.secretAccessKey, dateStamp, input.region, input.service)).update(stringToSign, "utf8").digest("hex");
    86	  const headers: Record<string, string> = {
    87	    "X-Amz-Date": date,
    88	    Authorization: `AWS4-HMAC-SHA256 Credential=${input.credentials.accessKeyId}/${scope}, SignedHeaders=${signedHeaders}, Signature=${signature}`,
    89	  };
    90	  if (input.credentials.sessionToken) headers["X-Amz-Security-Token"] = input.credentials.sessionToken;
    91	  return { headers, canonicalRequest, stringToSign, signature };
    92	}
