     1	/**
     2	 * AWS event-stream binary framing (application/vnd.amazon.eventstream), as used by ConverseStream.
     3	 * Frame: total length (4), headers length (4), prelude CRC32 (4), headers, payload, message CRC32 (4); big-endian.
     4	 * Header: name length (1), name, value type (1), value. Both CRCs are verified; any framing fault is malformed.
     5	 */
     6	import { ProviderStreamError } from "./common.js";
     7	
     8	export interface EventFrame {
     9	  headers: Record<string, string | number | boolean | Uint8Array>;
    10	  payload: Buffer;
    11	}
    12	
    13	/** A frame larger than this is treated as corrupt instead of buffered (AWS limits a message to 24 MiB). */
    14	const MAX_FRAME = 24 * 1024 * 1024;
    15	const MIN_FRAME = 16;
    16	
    17	const CRC_TABLE = (() => {
    18	  const t = new Uint32Array(256);
    19	  for (let n = 0; n < 256; n++) {
    20	    let c = n;
    21	    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    22	    t[n] = c >>> 0;
    23	  }
    24	  return t;
    25	})();
    26	
    27	export function crc32(buf: Uint8Array, start = 0, end = buf.length): number {
    28	  let c = 0xffffffff;
    29	  for (let i = start; i < end; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
    30	  return (c ^ 0xffffffff) >>> 0;
    31	}
    32	
    33	function bad(msg: string): ProviderStreamError {
    34	  return new ProviderStreamError(`Malformed event stream: ${msg}`, undefined, "", true);
    35	}
    36	
    37	function parseHeaders(buf: Buffer, start: number, end: number): EventFrame["headers"] {
    38	  const out: EventFrame["headers"] = {};
    39	  let p = start;
    40	  const need = (n: number) => {
    41	    if (p + n > end) throw bad("header overruns its block");
    42	  };
    43	  while (p < end) {
    44	    need(1);
    45	    const nameLen = buf[p++];
    46	    need(nameLen + 1);
    47	    const name = buf.toString("utf8", p, p + nameLen);
    48	    p += nameLen;
    49	    const type = buf[p++];
    50	    switch (type) {
    51	      case 0: out[name] = true; break;
    52	      case 1: out[name] = false; break;
    53	      case 2: need(1); out[name] = buf.readInt8(p); p += 1; break;
    54	      case 3: need(2); out[name] = buf.readInt16BE(p); p += 2; break;
    55	      case 4: need(4); out[name] = buf.readInt32BE(p); p += 4; break;
    56	      case 5: need(8); out[name] = Number(buf.readBigInt64BE(p)); p += 8; break;
    57	      case 8: need(8); out[name] = Number(buf.readBigInt64BE(p)); p += 8; break;
    58	      case 9: need(16); out[name] = buf.subarray(p, p + 16); p += 16; break;
    59	      case 6:
    60	      case 7: {
    61	        need(2);
    62	        const len = buf.readUInt16BE(p);
    63	        p += 2;
    64	        need(len);
    65	        out[name] = type === 7 ? buf.toString("utf8", p, p + len) : buf.subarray(p, p + len);
    66	        p += len;
    67	        break;
    68	      }
    69	      default:
    70	        throw bad(`unknown header value type ${type}`);
    71	    }
    72	  }
    73	  return out;
    74	}
    75	
    76	/** Incremental decoder: push chunks at any boundary, receive each complete frame. */
    77	export class EventStreamDecoder {
    78	  private buf = Buffer.alloc(0);
    79	
    80	  push(chunk: Uint8Array): EventFrame[] {
    81	    this.buf = this.buf.length ? Buffer.concat([this.buf, chunk]) : Buffer.from(chunk);
    82	    const frames: EventFrame[] = [];
    83	    while (this.buf.length >= 12) {
    84	      const total = this.buf.readUInt32BE(0);
    85	      const headersLen = this.buf.readUInt32BE(4);
    86	      if (total < MIN_FRAME || total > MAX_FRAME) throw bad(`frame length ${total} out of range`);
    87	      if (headersLen > total - MIN_FRAME) throw bad("headers length exceeds the frame");
    88	      if (crc32(this.buf, 0, 8) !== this.buf.readUInt32BE(8)) throw bad("prelude checksum mismatch");
    89	      if (this.buf.length < total) break;
    90	      if (crc32(this.buf, 0, total - 4) !== this.buf.readUInt32BE(total - 4)) throw bad("message checksum mismatch");
    91	      const headers = parseHeaders(this.buf, 12, 12 + headersLen);
    92	      frames.push({ headers, payload: Buffer.from(this.buf.subarray(12 + headersLen, total - 4)) });
    93	      this.buf = this.buf.subarray(total);
    94	    }
    95	    return frames;
    96	  }
    97	
    98	  /** Bytes of an unfinished frame left at end of stream. */
    99	  get pending(): number {
   100	    return this.buf.length;
   101	  }
   102	}
   103	
   104	/** Encodes one frame; used by tests and fixtures. Headers are strings (type 7). */
   105	export function encodeFrame(headers: Record<string, string>, payload: Uint8Array | string): Buffer {
   106	  const hdr = Buffer.concat(
   107	    Object.entries(headers).map(([k, v]) => {
   108	      const name = Buffer.from(k, "utf8");
   109	      const val = Buffer.from(v, "utf8");
   110	      const out = Buffer.alloc(1 + name.length + 1 + 2 + val.length);
   111	      let p = 0;
   112	      out[p++] = name.length;
   113	      name.copy(out, p); p += name.length;
   114	      out[p++] = 7;
   115	      out.writeUInt16BE(val.length, p); p += 2;
   116	      val.copy(out, p);
   117	      return out;
   118	    }),
   119	  );
   120	  const body = typeof payload === "string" ? Buffer.from(payload, "utf8") : Buffer.from(payload);
   121	  const total = 12 + hdr.length + body.length + 4;
   122	  const out = Buffer.alloc(total);
   123	  out.writeUInt32BE(total, 0);
   124	  out.writeUInt32BE(hdr.length, 4);
   125	  out.writeUInt32BE(crc32(out, 0, 8), 8);
   126	  hdr.copy(out, 12);
   127	  body.copy(out, 12 + hdr.length);
   128	  out.writeUInt32BE(crc32(out, 0, total - 4), total - 4);
   129	  return out;
   130	}
   131	
   132	/**
   133	 * Reads an event-stream body. `onEvent` gets the event name and the payload text: the `:event-type` for an event, and
   134	 * `exception:<type>` or `error:<code>` for an exception or error message (whose payload carries the provider's text).
   135	 */
   136	export async function readEventStream(
   137	  body: ReadableStream<Uint8Array>,
   138	  onEvent: (name: string | undefined, data: string) => void,
   139	  onChunk?: () => void,
   140	): Promise<void> {
   141	  const reader = body.getReader();
   142	  const decoder = new EventStreamDecoder();
   143	  try {
   144	    while (true) {
   145	      const { done, value } = await reader.read();
   146	      if (done) break;
   147	      onChunk?.();
   148	      for (const f of decoder.push(value)) {
   149	        const h = f.headers;
   150	        const kind = h[":message-type"];
   151	        const name =
   152	          kind === "exception" ? `exception:${String(h[":exception-type"] ?? "unknown")}`
   153	          : kind === "error" ? `error:${String(h[":error-code"] ?? "unknown")}`
   154	          : typeof h[":event-type"] === "string" ? (h[":event-type"] as string)
   155	          : undefined;
   156	        const text = f.payload.toString("utf8");
   157	        onEvent(name, name?.startsWith("error:") ? JSON.stringify({ message: String(h[":error-message"] ?? text) }) : text);
   158	      }
   159	    }
   160	    if (decoder.pending) throw bad("stream ended inside a frame");
   161	  } catch (err) {
   162	    try { await reader.cancel(); } catch {}
   163	    throw err;
   164	  }
   165	}
