     1	/**
     2	 * AWS credential chain, read-only, from environment variables and the shared credentials and config files:
     3	 *   1. AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY / AWS_SESSION_TOKEN
     4	 *   2. the profile (AWS_PROFILE, AWS_DEFAULT_PROFILE, else "default") in AWS_SHARED_CREDENTIALS_FILE
     5	 *      (default ~/.aws/credentials), then in AWS_CONFIG_FILE (default ~/.aws/config)
     6	 * Not supported: SSO, assume-role, credential_process and instance metadata (they need network or code execution).
     7	 * Values are never logged or put in error messages; errors name only the variable, file or profile.
     8	 */
     9	import fs from "node:fs";
    10	import os from "node:os";
    11	import path from "node:path";
    12	import type { AwsCredentials } from "./aws_sigv4.js";
    13	
    14	export interface AwsEnvironment {
    15	  env: Record<string, string | undefined>;
    16	  /** Home directory for the default file locations (tests pass a temporary directory). */
    17	  home?: string;
    18	  readFile?: (file: string) => string | undefined;
    19	}
    20	
    21	export type IniFile = Record<string, Record<string, string>>;
    22	
    23	/** INI with `[section]` headers, `key = value`, and `#` or `;` comment lines. Linear time; no regular expressions. */
    24	export function parseIni(text: string, configFile = false): IniFile {
    25	  const out: IniFile = {};
    26	  let section: Record<string, string> | undefined;
    27	  for (const raw of text.split("\n")) {
    28	    const line = raw.trim();
    29	    if (!line || line.startsWith("#") || line.startsWith(";")) continue;
    30	    if (line.startsWith("[") && line.endsWith("]")) {
    31	      let name = line.slice(1, -1).trim();
    32	      if (configFile) {
    33	        if (name.startsWith("profile ")) name = name.slice(8).trim();
    34	        else if (name !== "default") { section = undefined; continue; }
    35	      }
    36	      section = out[name] ??= {};
    37	      continue;
    38	    }
    39	    const eq = line.indexOf("=");
    40	    if (eq < 0 || !section) continue;
    41	    section[line.slice(0, eq).trim().toLowerCase()] = line.slice(eq + 1).trim();
    42	  }
    43	  return out;
    44	}
    45	
    46	function profileName(env: AwsEnvironment["env"]): string {
    47	  return env.AWS_PROFILE?.trim() || env.AWS_DEFAULT_PROFILE?.trim() || "default";
    48	}
    49	
    50	function reader(e: AwsEnvironment): (file: string) => string | undefined {
    51	  return e.readFile ?? ((file) => {
    52	    try { return fs.readFileSync(file, "utf8"); } catch { return undefined; }
    53	  });
    54	}
    55	
    56	function files(e: AwsEnvironment): { credentials: string; config: string } {
    57	  const home = e.home ?? os.homedir();
    58	  return {
    59	    credentials: e.env.AWS_SHARED_CREDENTIALS_FILE?.trim() || path.join(home, ".aws", "credentials"),
    60	    config: e.env.AWS_CONFIG_FILE?.trim() || path.join(home, ".aws", "config"),
    61	  };
    62	}
    63	
    64	export class AwsCredentialError extends Error {}
    65	
    66	export function resolveAwsCredentials(e: AwsEnvironment): AwsCredentials {
    67	  const id = e.env.AWS_ACCESS_KEY_ID?.trim();
    68	  const secret = e.env.AWS_SECRET_ACCESS_KEY?.trim();
    69	  if (id && secret) return { accessKeyId: id, secretAccessKey: secret, ...(e.env.AWS_SESSION_TOKEN?.trim() ? { sessionToken: e.env.AWS_SESSION_TOKEN.trim() } : {}) };
    70	  if (id || secret) throw new AwsCredentialError("AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY must both be set");
    71	  const profile = profileName(e.env);
    72	  const read = reader(e);
    73	  const f = files(e);
    74	  const sources: Array<[string, boolean]> = [[f.credentials, false], [f.config, true]];
    75	  for (const [file, isConfig] of sources) {
    76	    const text = read(file);
    77	    if (text === undefined) continue;
    78	    const s = parseIni(text, isConfig)[profile];
    79	    const keyId = s?.aws_access_key_id;
    80	    const key = s?.aws_secret_access_key;
    81	    if (keyId && key) return { accessKeyId: keyId, secretAccessKey: key, ...(s.aws_session_token ? { sessionToken: s.aws_session_token } : {}) };
    82	  }
    83	  throw new AwsCredentialError(`no AWS credentials: set AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY, or add profile '${profile}' to ${f.credentials}`);
    84	}
    85	
    86	const REGION = /^[a-z]{2}(?:-[a-z]+)+-\d{1,2}$/;
    87	
    88	/** AWS_REGION, AWS_DEFAULT_REGION, then `region` in the profile of the config file. */
    89	export function resolveAwsRegion(e: AwsEnvironment): string | undefined {
    90	  const fromEnv = e.env.AWS_REGION?.trim() || e.env.AWS_DEFAULT_REGION?.trim();
    91	  if (fromEnv) return fromEnv;
    92	  const text = reader(e)(files(e).config);
    93	  const region = text === undefined ? undefined : parseIni(text, true)[profileName(e.env)]?.region;
    94	  return region || undefined;
    95	}
    96	
    97	export function isAwsRegion(value: string): boolean {
    98	  return REGION.test(value);
    99	}

