    13	import { signSigV4 } from "./aws_sigv4.js";
    14	import {
    15	  argumentsObject,
    16	  num,
    17	  ownedState,
    18	  ProviderStreamError,
    19	  stateDigest,
    20	  textOf,
    21	  wireToolId,
    22	  type NativeFinish,
