    38	  for (const p of content as any[]) {
    39	    if (typeof p === "string") out.push({ text: p });
    40	    else if (p?.type === "text" && p.text) out.push({ text: p.text });
    41	    else if (p?.type === "image_url" && typeof p.image_url?.url === "string") {
