   163	export function bedrockStreamParser(owner: string, onToken?: (t: string) => void): StreamParser {
   164	  const blocks: Block[] = [];
   165	  const open = new Set<number>();
   166	  let stop: string | undefined;
   167	  let stopped = false;
   168	  let usage: UsageReport | undefined;
