  1	/**
  2	 * Google Gemini `generateContent` / `streamGenerateContent` (Generative Language API): request projection from Nexus
  3	 * history and assembly of streamed/non-streamed responses.
  4	 *
  5	 * The model is part of the URL path, so `build` returns `/models/<model>:generateContent` (or the streaming method
  6	 * with `alt=sse`). Parallel tool calls are several `functionCall` parts of one model turn; their results go back as
  7	 * several `functionResponse` parts of one user turn, in call order. Gemini pairs results by name and position, so the
  8	 * name comes from the assistant turn that made the call. Thought-summary parts (`thought: true`) are shown to nobody
  9	 * and never replayed; every other part, including its `thoughtSignature`, is kept as provider_state owned by
 10	 * "<provider>:<model>" and replayed verbatim only to that owner (Gemini 3 rejects a tool turn that lost its signature).
 11	 * A stream is complete only once a chunk carries a `finishReason`.
 12	 */
 13	import { randomBytes } from "node:crypto";
 14	import type { ChatMessage, ToolCall } from "../types.js";
 15	import type { UsageReport } from "../usage.js";
 16	import {
 17	  argumentsObject,
 18	  num,
 19	  ownedState,
 20	  ProviderStreamError,
 21	  stateDigest,
 22	  textOf,
 23	  type NativeFinish,
 24	  type NativeRequest,
 25	  type NativeRequestInput,
 26	  type NativeResult,
 27	  type StreamParser,
 28	} from "./common.js";
 29	
 30	type Part = Record<string, any>;
 31	interface Turn { role: "user" | "model"; parts: Part[] }
 32	
 33	function userParts(content: ChatMessage["content"]): Part[] {
 34	  if (!Array.isArray(content)) {
 35	    const t = textOf(content);
 36	    return t ? [{ text: t }] : [];
 37	  }
 38	  const out: Part[] = [];
 39	  for (const p of content as any[]) {
 40	    if (typeof p === "string") out.push({ text: p });
 41	    else if (p?.type === "text" && p.text) out.push({ text: p.text });
 42	    else if (p?.type === "image_url" && typeof p.image_url?.url === "string") {
 43	      const url: string = p.image_url.url;
 44	      const m = /^data:([^;,]+);base64,/.exec(url);
 45	      out.push(m ? { inlineData: { mimeType: m[1], data: url.slice(m[0].length) } } : { fileData: { fileUri: url } });
 46	    }
 47	  }
 48	  return out;
 49	}
 50	
 51	/** `models/gemini-x` and `gemini-x` name the same model; the path always gets the bare, encoded id. */
 52	function modelPath(model: string, stream: boolean): string {
 53	  const id = model.replace(/^models\//, "");
 54	  return `/models/${encodeURIComponent(id)}:${stream ? "streamGenerateContent?alt=sse" : "generateContent"}`;
 55	}
 56	
 57	export function buildGeminiRequest(input: NativeRequestInput): NativeRequest {
 58	  const systemParts: string[] = [];
 59	  const turns: Turn[] = [];
 60	  const names = new Map<string, string>(); // tool call id -> function name
 61	  let droppedState = 0;
 62	  let seenNonSystem = false;
 63	  const push = (role: Turn["role"], parts: Part[]) => {
 64	    if (!parts.length) return;
 65	    const last = turns[turns.length - 1];
 66	    if (last && last.role === role) last.parts.push(...parts);
 67	    else turns.push({ role, parts });
 68	  };
 69	  for (const m of input.messages) {
 70	    if (m.role === "system") {
 71	      const t = textOf(m.content);
 72	      if (!seenNonSystem) systemParts.push(t);
 73	      else if (t) push("user", [{ text: `[System notice]\n${t}` }]);
 74	      continue;
 75	    }
 76	    seenNonSystem = true;
 77	    if (m.role === "user") push("user", userParts(m.content));
 78	    else if (m.role === "tool") {
 79	      const content = typeof m.content === "string" ? m.content : JSON.stringify(m.content ?? "");
 80	      const name = names.get(m.tool_call_id ?? "") ?? m.name ?? "tool";
 81	      push("user", [{ functionResponse: { name, response: { output: content || "(no output)" } } }]);
 82	    } else {
 83	      for (const tc of m.tool_calls ?? []) names.set(tc.id, tc.function.name);
 84	      const owned = ownedState(m, input.owner);
 85	      if (m.provider_state && !owned) droppedState++;
 86	      const parts: Part[] = [];
 87	      if (owned) parts.push(...owned);
 88	      else {
 89	        const t = textOf(m.content);
 90	        if (t.trim()) parts.push({ text: t });
 91	        for (const tc of m.tool_calls ?? []) parts.push({ functionCall: { name: tc.function.name, args: argumentsObject(tc.function.arguments) } });
 92	      }
 93	      push("model", parts.length ? parts : [{ text: "(no content)" }]);
 94	    }
 95	  }
 96	  if (turns[0]?.role !== "user") turns.unshift({ role: "user", parts: [{ text: "(continue)" }] });
 97	
 98	  const generationConfig: Record<string, unknown> = { maxOutputTokens: input.maxOutputTokens };
 99	  if (input.temperature !== undefined) generationConfig.temperature = input.temperature;
100	  const level = input.reasoningEffort?.toLowerCase();
101	  if (input.thinkingBudget !== undefined) {
102	    generationConfig.thinkingConfig = { includeThoughts: true, thinkingBudget: Math.max(0, Math.floor(input.thinkingBudget)) };
103	  } else if (level === "minimal" || level === "low" || level === "medium" || level === "high") {
104	    generationConfig.thinkingConfig = { includeThoughts: true, thinkingLevel: level };
105	  }
106	
107	  const body: Record<string, unknown> = { contents: turns, generationConfig };
108	  const system = systemParts.filter(Boolean).join("\n\n");
109	  if (system) body.systemInstruction = { parts: [{ text: system }] };
110	  if (input.tools.length) {
111	    // parametersJsonSchema takes the schema as written; the OpenAPI-subset `parameters` field rejects common keywords.
112	    body.tools = [{ functionDeclarations: input.tools.map((t) => ({ name: t.function.name, description: t.function.description, parametersJsonSchema: t.function.parameters })) }];
113	  }
114	  return { path: modelPath(input.model, input.stream), body, droppedState };
115	}
116	
117	const REFUSALS = new Set(["SAFETY", "RECITATION", "BLOCKLIST", "PROHIBITED_CONTENT", "SPII", "IMAGE_SAFETY", "LANGUAGE"]);
118	
119	function finishOf(reason: string | undefined, hasTools: boolean): NativeFinish {
120	  if (reason === "MAX_TOKENS") return "length";
121	  if (reason && REFUSALS.has(reason)) return "refusal";
122	  return hasTools ? "tool_calls" : "stop";
123	}
124	
125	function usageOf(u: any): UsageReport | undefined {
126	  if (!u || typeof u !== "object") return undefined;
127	  const r: UsageReport = {};
128	  if (num(u.promptTokenCount) !== undefined) r.inputTokens = u.promptTokenCount;
129	  // Gemini reports thinking tokens apart from candidatesTokenCount; output here includes them, as in Chat Completions.
130	  if (num(u.candidatesTokenCount) !== undefined || num(u.thoughtsTokenCount) !== undefined) r.outputTokens = (num(u.candidatesTokenCount) ?? 0) + (num(u.thoughtsTokenCount) ?? 0);
131	  if (num(u.cachedContentTokenCount) !== undefined) r.cachedInputTokens = u.cachedContentTokenCount;
132	  if (num(u.thoughtsTokenCount) !== undefined) r.reasoningTokens = u.thoughtsTokenCount;
133	  return r;
134	}
135	
136	function callId(part: Part): string {
137	  return typeof part.functionCall?.id === "string" && part.functionCall.id ? part.functionCall.id : `call_${randomBytes(6).toString("hex")}`;
138	}
139	
140	function assemble(parts: Part[], owner: string, reason: string | undefined, usage: UsageReport | undefined, id?: string, model?: string): NativeResult {
141	  let text = "";
142	  const toolCalls: ToolCall[] = [];
143	  const kept: Part[] = [];
144	  for (const p of parts) {
145	    if (p.thought === true) continue;
146	    kept.push(p);
147	    if (typeof p.text === "string") text += p.text;
148	    if (p.functionCall && typeof p.functionCall.name === "string") {
149	      const args = typeof p.functionCall.args === "object" && p.functionCall.args !== null ? p.functionCall.args : {};
150	      toolCalls.push({ id: callId(p), type: "function", function: { name: p.functionCall.name, arguments: JSON.stringify(args) } });
151	    }
152	  }
153	  const signed = kept.some((p) => typeof p.thoughtSignature === "string");
154	  const message: ChatMessage = {
155	    role: "assistant",
156	    content: text || null,
157	    ...(toolCalls.length ? { tool_calls: toolCalls } : {}),
158	    ...(signed ? { provider_state: { owner, items: kept, digest: stateDigest(kept) } } : {}),
159	  };
160	  return { message, finish: finishOf(reason, toolCalls.length > 0), usage, providerRequestId: id, effectiveModel: model, text };
161	}
162	
163	function blocked(data: any): string | undefined {
164	  const reason = data?.promptFeedback?.blockReason;
165	  return typeof reason === "string" ? reason : undefined;
166	}
167	
168	export function parseGeminiResponse(data: any, owner: string): NativeResult {
169	  if (data?.error) throw new ProviderStreamError(`Gemini error: ${data.error.message ?? JSON.stringify(data.error)}`, data.error.status, "");
170	  const cand = Array.isArray(data?.candidates) ? data.candidates[0] : undefined;
171	  if (!cand) {
172	    if (blocked(data)) return { message: { role: "assistant", content: null }, finish: "refusal", usage: usageOf(data.usageMetadata), providerRequestId: data.responseId, effectiveModel: data.modelVersion, text: "" };
173	    throw new ProviderStreamError("Gemini response has no candidates", undefined, "", true);
174	  }
175	  if (cand.finishReason === "MALFORMED_FUNCTION_CALL") throw new ProviderStreamError("Gemini produced a malformed function call", cand.finishReason, "", true);
176	  const parts = Array.isArray(cand.content?.parts) ? cand.content.parts : [];
177	  return assemble(parts, owner, cand.finishReason, usageOf(data.usageMetadata), data.responseId, data.modelVersion);
178	}
179	
180	export function geminiStreamParser(owner: string, onToken?: (t: string) => void): StreamParser {
181	  const parts: Part[] = [];
182	  let reason: string | undefined;
183	  let usage: UsageReport | undefined;
184	  let id: string | undefined;
185	  let model: string | undefined;
186	  let text = "";
187	  let sawBlock: string | undefined;
188	  return {
189	    text: () => text,
190	    event(_name, ev) {
191	      if (ev?.error) throw new ProviderStreamError(`Provider error frame mid-stream: ${ev.error.message ?? JSON.stringify(ev.error)}`, ev.error.status, text);
192	      id = ev?.responseId ?? id;
193	      model = ev?.modelVersion ?? model;
194	      usage = usageOf(ev?.usageMetadata) ?? usage;
195	      sawBlock = blocked(ev) ?? sawBlock;
196	      const cand = Array.isArray(ev?.candidates) ? ev.candidates[0] : undefined;
197	      if (!cand) return;
198	      for (const p of Array.isArray(cand.content?.parts) ? cand.content.parts : []) {
199	        const last = parts[parts.length - 1];
200	        // Consecutive text fragments of the same kind (answer or thought) are one part; a signature rides the fragment it signs.
201	        if (typeof p.text === "string" && last && typeof last.text === "string" && Boolean(last.thought) === Boolean(p.thought) && !last.thoughtSignature) {
202	          last.text += p.text;
203	          if (p.thoughtSignature) last.thoughtSignature = p.thoughtSignature;
204	        } else parts.push({ ...p });
205	        if (typeof p.text === "string" && p.thought !== true && p.text) {
206	          text += p.text;
207	          onToken?.(p.text);
208	        }
209	      }
210	      if (cand.finishReason) reason = cand.finishReason;
211	    },
212	    result() {
213	      if (!reason) {
214	        if (sawBlock && parts.length === 0) return { message: { role: "assistant", content: null }, finish: "refusal", usage, providerRequestId: id, effectiveModel: model, text };
215	        return { message: { role: "assistant", content: text || null }, finish: "incomplete", usage, providerRequestId: id, effectiveModel: model, text };
216	      }
217	      if (reason === "MALFORMED_FUNCTION_CALL") throw new ProviderStreamError("Gemini produced a malformed function call", reason, text, true);
218	      return assemble(parts, owner, reason, usage, id, model);
219	    },
220	  };
221	}

