  1	/**
  2	 * CS-7: a deterministic scanner for prompt injection in content that enters the model from outside (a fetched page, a
  3	 * file, a command's output, a tool server's answer). It looks for four things:
  4	 *
  5	 *  - instruction-like text aimed at the assistant ("ignore the previous instructions", "do not tell the user",
  6	 *    "send the credentials to ..."),
  7	 *  - characters a reader cannot see (Unicode tag characters that spell hidden text, bidirectional overrides, runs of
  8	 *    zero-width characters),
  9	 *  - markup that poses as a chat turn or a tool call (`<|im_start|>`, `<tool_call>`, a `{"role":"system"}` message,
 10	 *    a pasted `Human:` / `Assistant:` transcript),
 11	 *  - a base64 or percent-encoded payload that decodes to one of the above.
 12	 *
 13	 * It is a heuristic, not a guarantee, and says so everywhere it speaks. It reads English phrasing; a paraphrase, another
 14	 * language, text split across lines or words, and anything the model is talked into by content that carries no
 15	 * instruction words are not seen (the corpus in test/fixtures/injection_corpus.json records what it misses and what it
 16	 * wrongly flags, with the measured rates). It never removes content: a flagged result is labelled and fenced by the
 17	 * caller, and the only change made inside the fence is that hidden characters are shown as `<U+XXXX>`.
 18	 *
 19	 * Every pattern starts with a literal and has only bounded runs, so matching is linear-time on any input.
 20	 */
 21	import { TEMPLATE_TOKEN } from "../skills.js";
 22	
 23	export type InjectionSignal = "instruction" | "hidden_unicode" | "fake_markup" | "encoded_payload" | "markdown_exfil";
 24	
 25	export interface InjectionFinding {
 26	  signal: InjectionSignal;
 27	  rule: string;
 28	  strength: "strong" | "weak";
 29	  /** A short, escaped excerpt of what matched (never more than 80 characters). */
 30	  evidence: string;
 31	}
 32	
 33	export interface InjectionScan {
 34	  suspected: boolean;
 35	  findings: InjectionFinding[];
 36	  /** Text a hidden-character run spells out (Unicode tag characters decode to ASCII), when any. */
 37	  hiddenText?: string;
 38	  /** The scan covered only the first MAX_SCAN_CHARS characters. */
 39	  truncated: boolean;
 40	}
 41	
 42	/** One scan reads at most this much of a result; the rest is reported as not scanned. */
 43	export const MAX_SCAN_CHARS = 200_000;
 44	const MAX_BASE64_RUNS = 20;
 45	const MAX_ENCODED_CHARS = 20_000;
 46	
 47	interface Rule {
 48	  id: string;
 49	  strength: "strong" | "weak";
 50	  signal: InjectionSignal;
 51	  pattern: RegExp;
 52	}
 53	
 54	const GAP = "(?:all |any |the |your |my |these |those |every ){0,2}";
 55	const RULES: Rule[] = [
 56	  { id: "ignore-previous-instructions", strength: "strong", signal: "instruction", pattern: new RegExp(`\\b(?:ignore|disregard|forget|override|bypass|discard) ${GAP}(?:previous|prior|above|earlier|preceding|former|original|system|existing) (?:instructions?|prompts?|messages?|rules?|directions?|guidelines?|context|commands?|constraints?)`, "i") },
 57	  { id: "instructions-outdated", strength: "strong", signal: "instruction", pattern: /\b(?:instructions?|rules?|prompts?|guidelines?) (?:above|before|so far|given earlier|you were given) (?:are|is|were|have been) (?:now )?(?:outdated|obsolete|wrong|void|invalid|cancell?ed|superseded|revoked)/i },
 58	  { id: "forget-everything", strength: "strong", signal: "instruction", pattern: /\bforget (?:everything|all) (?:you|that|above|before|i)\b/i },
 59	  { id: "reveal-system-prompt", strength: "strong", signal: "instruction", pattern: /\b(?:reveal|print|show|output|repeat|leak|display|disclose) (?:me )?(?:your|the) (?:system prompt|initial prompt|hidden instructions?|instructions? above|secret instructions?)/i },
 60	  { id: "conceal-from-user", strength: "strong", signal: "instruction", pattern: /\b(?:do not|don't|never|without) (?:tell|telling|inform|informing|mention|mentioning|reveal|show|showing|alert|notify|let) (?:to |this )?(?:the |this )?(?:user|human|operator|owner|developer)/i },
 61	  { id: "conceal-instruction", strength: "strong", signal: "instruction", pattern: /\b(?:never|do not|don't) (?:reveal|show|disclose|share) (?:this|these|the) (?:instructions?|message|prompt|text|note) (?:to|with) (?:the )?(?:user|human|operator|owner)/i },
 62	  { id: "keep-secret-from-user", strength: "strong", signal: "instruction", pattern: /\bkeep (?:this|that|it|these) (?:a )?secret from (?:the |this )?(?:user|human|operator|owner|developer)/i },
 63	  { id: "new-instructions", strength: "strong", signal: "instruction", pattern: /\b(?:new|updated|revised|real|actual|true) (?:system )?(?:instructions?|task|objective|directive|orders?):/i },
 64	  { id: "note-to-ai", strength: "strong", signal: "instruction", pattern: /\b(?:note|message|attention|instruction|hey|hello|dear|important)s? (?:to|for) (?:the |any |all )?(?:ai|assistant|agent|llm|language model|model|chatbot|claude|chatgpt|copilot|gemini|gpt)\b/i },
 65	  { id: "ai-then-imperative", strength: "strong", signal: "instruction", pattern: /\b(?:ai|assistants?|agents?|llms?|models?)[,:] (?:you (?:must|should|need to|will|are required to)|please (?:do|run|execute|send|ignore|delete|read|fetch|download)|ignore|disregard|do not)\b/i },
 66	  { id: "send-secrets", strength: "strong", signal: "instruction", pattern: /\b(?:send|post|upload|email|forward|transmit|exfiltrate|leak) (?:[a-z'\u2019]+ ){0,4}(?:secrets?|credentials?|passwords?|tokens?|api ?keys?|private keys?|\.env|environment variables?|ssh keys?|cookies|conversation|chat history|system prompt)\b/i },
 67	  { id: "copy-credentials-out", strength: "strong", signal: "instruction", pattern: /\b(?:copy|paste|upload|send|post|push) [^\n]{0,60}(?:\.aws\/credentials|\.ssh\/id_[a-z0-9]{1,12}|\.env\b|\.netrc|credentials\.json)[^\n]{0,40}(?:gist|pastebin|webhook|https?:|server|email|public)/i },
 68	  { id: "you-are-now", strength: "weak", signal: "instruction", pattern: /\byou are now (?:in )?(?:a |an |the )?(?:[a-z-]+ ){0,3}(?:mode|assistant|ai|agent|bot|persona|character)\b/i },
 69	  { id: "from-now-on-you", strength: "weak", signal: "instruction", pattern: /\bfrom now on[^\n]{0,60}\b(?:you|your)\b/i },
 70	  { id: "special-mode", strength: "weak", signal: "instruction", pattern: /\b(?:developer|god|sudo|jailbreak|dan) mode\b/i },
 71	  { id: "pretend-you", strength: "weak", signal: "instruction", pattern: /\bpretend (?:that )?you (?:are|have|can|were)\b/i },
 72	  { id: "markdown-image-exfil", strength: "strong", signal: "markdown_exfil", pattern: /!\[[^\]\n]{0,40}\]\(https?:\/\/[^)\s]{1,200}[?&][a-z]{1,16}=(?:\[|\{|<|%7B|\$\{)/i },
 73	  { id: "tool-call-markup", strength: "weak", signal: "fake_markup", pattern: /<\/?(?:tool_call|function_calls?|invoke|tool_use|antml:[a-z_]{1,32})[ >\/]/i },
 74	  { id: "tool-calls-json", strength: "weak", signal: "fake_markup", pattern: /"(?:tool_calls|function_call)"\s*:\s*[[{]/i },
 75	  { id: "system-message-json", strength: "weak", signal: "fake_markup", pattern: /"role"\s*:\s*"(?:system|developer)"/i },
 76	];
 77	
 78	/** Strong rules that are re-run on a decoded payload (an encoded phrase that matches only a weak rule is not reported). */
 79	const DECODED_RULES = RULES.filter((r) => r.strength === "strong" && r.signal !== "markdown_exfil");
 80	
 81	/** A private, non-global copy: `.test()` on a global pattern keeps state between calls. */
 82	const TEMPLATE_ONCE = new RegExp(TEMPLATE_TOKEN.source, "i");
 83	const TRANSCRIPT_TURN = /^(?:human|user|assistant|system|ai): /gim;
 84	const BIDI_CONTROL = /[\u202a-\u202e\u2066-\u2069]/g;
 85	const ZERO_WIDTH = /[\u200b\u2060\ufeff]/g;
 86	const VARIATION_RUN = /[\u{E0100}-\u{E01EF}]{4,}/u;
 87	const TAG_CHARACTER = /[\u{E0000}-\u{E007F}]/gu;
 88	const BASE64_RUN = /[A-Za-z0-9+/]{120,}={0,2}/g;
 89	const PERCENT_RUN = /(?:%[0-9a-fA-F]{2}){24,}/g;
 90	
 91	const escape = (text: string): string => text.replace(/[^\x20-\x7e]/gu, (c) => `\\u{${c.codePointAt(0)!.toString(16)}}`).slice(0, 80);
 92	
 93	function excerpt(text: string, index: number, length: number): string {
 94	  return escape(text.slice(Math.max(0, index - 10), index + Math.min(length, 60) + 10).replace(/\s+/g, " "));
 95	}
 96	
 97	/** What a run of Unicode tag characters says: each U+E0020..U+E007E maps to the ASCII character 0x20..0x7E. */
 98	export function decodeTagCharacters(text: string): string {
 99	  let out = "";
100	  for (const ch of text.matchAll(TAG_CHARACTER)) {
101	    const code = ch[0].codePointAt(0)! - 0xe0000;
102	    if (code >= 0x20 && code <= 0x7e) out += String.fromCharCode(code);
103	  }
104	  return out;
105	}
106	
107	/** Hidden characters shown as `<U+XXXX>`; every other character is left exactly as it was. */
108	export function revealHiddenCharacters(text: string): string {
109	  return text.replace(/[\u202a-\u202e\u2066-\u2069\u200b\u2060\ufeff\u{E0000}-\u{E007F}\u{E0100}-\u{E01EF}]/gu, (c) => `<U+${c.codePointAt(0)!.toString(16).toUpperCase().padStart(4, "0")}>`);
110	}
111	
