  1	/**
  2	 * CX-2: an auditable record of each compaction, kept beside the archive of the originals it replaced.
  3	 *
  4	 * A compaction replaces earlier messages with a shorter form. Its record names what it covered (a content-addressed id
  5	 * per message, in order, and one digest over them), where the replacement was inserted and what it was, so the
  6	 * compaction can be checked on resume and undone: the originals are in the archive, and `fullTranscript` puts them back.
  7	 * The record rides on the first archive line of its compaction as an extra key, so builds that predate it read the same
  8	 * file unchanged (they ignore the key) and a compaction with no record is simply not auditable.
  9	 */
 10	import { createHash } from "node:crypto";
 11	import type { ChatMessage } from "../types.js";
 12	
 13	export const COMPACTION_RECORD_VERSION = 1;
 14	/** Ids listed per record; a larger compaction keeps its count and digest and says the list was cut. */
 15	export const MAX_COVERED_IDS = 4096;
 16	
 17	export interface CompactionRecord {
 18	  v: typeof COMPACTION_RECORD_VERSION;
 19	  trigger: string;
 20	  /** Content-addressed ids (16 hex characters of the message's SHA-256) of the messages this compaction replaced, in order. */
 21	  coveredIds: string[];
 22	  coveredIdsTruncated?: true;
 23	  coveredCount: number;
 24	  /** SHA-256 over every covered message's full id, in order: the hash of the covered prefix. */
 25	  coveredSha256: string;
 26	  /** Where in the compacted conversation the new messages sit (index of the first), and what they were. */
 27	  inserted: { at: number; count: number; sha256: string; chars: number } | null;
 28	  beforeTokens: number;
 29	  afterTokens: number;
 30	}
 31	
 32	const sha256 = (text: string): string => createHash("sha256").update(text).digest("hex");
 33	
 34	/** Canonical JSON of a stored message: keys in sorted order at every depth, so the same message always hashes the same. */
 35	function canonical(value: unknown): string {
 36	  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
 37	  if (value && typeof value === "object") {
 38	    const record = value as Record<string, unknown>;
 39	    return `{${Object.keys(record).sort().filter((k) => record[k] !== undefined).map((k) => `${JSON.stringify(k)}:${canonical(record[k])}`).join(",")}}`;
 40	  }
 41	  return JSON.stringify(value) ?? "null";
 42	}
 43	
 44	/** The full id of a message: SHA-256 of its canonical stored form. */
 45	export const messageDigest = (message: unknown): string => sha256(canonical(message));
 46	
 47	/** The record of a compaction. `covered` and `inserted` are in their stored (persistence-protected) form, the one the archive and the session record hold. */
 48	export function buildCompactionRecord(input: {
 49	  trigger: string;
 50	  covered: ChatMessage[];
 51	  inserted: ChatMessage[];
 52	  insertedAt: number;
 53	  beforeTokens: number;
 54	  afterTokens: number;
 55	}): CompactionRecord {
 56	  const digests = input.covered.map(messageDigest);
 57	  const record: CompactionRecord = {
 58	    v: COMPACTION_RECORD_VERSION,
 59	    trigger: input.trigger,
 60	    coveredIds: digests.slice(0, MAX_COVERED_IDS).map((d) => d.slice(0, 16)),
 61	    coveredCount: digests.length,
 62	    coveredSha256: sha256(digests.join("\n")),
 63	    inserted: input.inserted.length
