 44	export type ProbeVerdict =
 45	  | { ok: true }
 46	  | { ok: false; reason: "missing"; missing: string[] }
 47	  | { ok: false; reason: "unverifiable"; detail: string };
 48	
 49	/** Reads the probe's answer strictly. Anything that is not a `{"missing": [...]}` object is "unverifiable", never a pass. */
 50	export function parseProbeAnswer(content: unknown, requirements: readonly ProbeRequirement[]): ProbeVerdict {
 51	  if (typeof content !== "string" || !content.trim()) return { ok: false, reason: "unverifiable", detail: "the check returned no answer" };
 52	  const match = /\{[\s\S]*\}/.exec(content);
 53	  let parsed: unknown;
 54	  try {
 55	    parsed = match ? JSON.parse(match[0]) : undefined;
 56	  } catch {
 57	    parsed = undefined;
 58	  }
 59	  const missing = (parsed as { missing?: unknown } | undefined)?.missing;
 60	  if (!Array.isArray(missing) || !missing.every((id) => typeof id === "string")) {
 61	    return { ok: false, reason: "unverifiable", detail: "the check's answer was not a {\"missing\": [...]} object" };
 62	  }
 63	  const known = new Set(requirements.map((r) => r.id));
 64	  const named = [...new Set((missing as string[]).filter((id) => known.has(id)))];
 65	  if (named.length) return { ok: false, reason: "missing", missing: named };
 66	  // An answer naming only ids that are not requirements says nothing about the real ones.
 67	  if (missing.length) return { ok: false, reason: "unverifiable", detail: "the check named requirements that do not exist" };
