  1	/**
  2	 * Reading paths out of a unified diff: Git's C-quoted paths, `a/` and `b/` prefixes, rename headers, and the list of
  3	 * every file a diff touches. Shared by the independent-review gate and the boundary check.
  4	 */
  5	
  6	/**
  7	 * Reads one path token as Git writes it: either bare, or C-quoted ("a/\303\251.ts", with \t, \", \\ and octal
  8	 * byte escapes) when the path contains non-ASCII bytes, tabs, quotes or backslashes. Returns the decoded path and
  9	 * the text after the token.
 10	 */
 11	function readGitPath(text: string): { path: string; rest: string } | undefined {
 12	  if (!text.startsWith('"')) return undefined;
 13	  const bytes: number[] = [];
 14	  const named: Record<string, number> = { a: 7, b: 8, t: 9, n: 10, v: 11, f: 12, r: 13, '"': 34, "\\": 92 };
 15	  for (let i = 1; i < text.length; i++) {
 16	    const ch = text[i];
 17	    if (ch === '"') {
 18	      return { path: Buffer.from(bytes).toString("utf-8"), rest: text.slice(i + 1) };
 19	    }
 20	    if (ch !== "\\") {
 21	      bytes.push(...Buffer.from(ch, "utf-8"));
 22	      continue;
 23	    }
 24	    const next = text[++i];
 25	    if (next === undefined) return undefined;
 26	    if (/[0-7]/.test(next)) {
 27	      const octal = text.slice(i, i + 3);
 28	      if (!/^[0-7]{3}$/.test(octal)) return undefined;
 29	      bytes.push(parseInt(octal, 8));
 30	      i += 2;
 31	    } else if (next in named) {
 32	      bytes.push(named[next]);
 33	    } else {
 34	      return undefined;
 35	    }
 36	  }
 37	  return undefined; // unterminated quote
 38	}
 39	
 40	/** Strips the a/ or b/ prefix Git adds; /dev/null means "no file on this side". */
 41	export function diffSidePath(raw: string, prefix: "a/" | "b/"): string | undefined {
 42	  const path = raw.startsWith(prefix) ? raw.slice(prefix.length) : raw;
 43	  return path === "/dev/null" || path === "dev/null" || raw === "/dev/null" ? undefined : path;
 44	}
 45	
 46	/** Parses the path written after `---`/`+++`/`rename from`/`rename to`, quoted or bare (bare runs to end of line). */
 47	export function headerPath(text: string): string | undefined {
 48	  if (text.startsWith('"')) return readGitPath(text)?.path;
 49	  const bare = text.replace(/\t.*$/, ""); // GNU diff may append a tab and timestamp
 50	  return bare || undefined;
 51	}
 52	
 53	/**
 54	 * Lists every file a unified diff touches, on both sides of renames, from `diff --git`, `---`/`+++` and
 55	 * `rename from`/`rename to` headers. Handles Git's C-quoted paths and bare paths containing spaces.
 56	 * A header that cannot be parsed yields a sentinel entry so the scope check fails closed instead of skipping it.
 57	 */
 58	export function extractModifiedFilesFromDiff(diff: string): string[] {
 59	  const modified = new Set<string>();
 60	  const add = (p: string | undefined) => {
 61	    if (p) modified.add(p);
 62	  };
 63	  // File headers (---/+++/rename) only appear outside a hunk. A hunk's `@@ -a,b +c,d @@` line says exactly how many
 64	  // old and new lines follow, so those lines are consumed by count: a removed line "-- note" is written "--- note"
 65	  // and an added "++ note" is written "+++ note", and neither is a path. A count that is omitted means 1.
 66	  let inHeader = true;
 67	  let oldLeft = 0;
 68	  let newLeft = 0;
 69	  const lines = diff.split("\n");
 70	  for (let i = 0; i < lines.length; i++) {
 71	    const line = lines[i];
 72	    if (oldLeft > 0 || newLeft > 0) {
 73	      // A file header pair followed by a hunk header cannot be hunk content (a body line never starts with "@@"), so a
 74	      // hunk whose counts overstate its body must not swallow the next file's headers.
 75	      if (line.startsWith("--- ") && lines[i + 1]?.startsWith("+++ ") && lines[i + 2]?.startsWith("@@")) {
 76	        oldLeft = 0;
 77	        newLeft = 0;
 78	      } else if (line.startsWith("\\")) continue; // "\ No newline at end of file"
 79	      if (line.startsWith(" ") || line === "") {
 80	        oldLeft = Math.max(0, oldLeft - 1);
 81	        newLeft = Math.max(0, newLeft - 1);
 82	        continue;
 83	      }
 84	      if (line.startsWith("-") && oldLeft > 0) {
 85	        oldLeft--;
 86	        continue;
 87	      }
 88	      if (line.startsWith("+") && newLeft > 0) {
 89	        newLeft--;
 90	        continue;
 91	      }
 92	      // The hunk ended earlier than its header promised: read this line as structure, not content.
 93	      oldLeft = 0;
 94	      newLeft = 0;
 95	    }
 96	    // A plain unified diff (no "diff --git" lines) starts each later file with a "---"/"+++" pair.
 97	    if (!inHeader && line.startsWith("--- ") && lines[i + 1]?.startsWith("+++ ")) inHeader = true;
 98	    if (line.startsWith("@@")) {
 99	      inHeader = false;
100	      const counts = /^@@ -\d+(?:,(\d+))? \+\d+(?:,(\d+))? @@/.exec(line);
101	      if (counts) {
102	        oldLeft = counts[1] === undefined ? 1 : Number(counts[1]);
103	        newLeft = counts[2] === undefined ? 1 : Number(counts[2]);
104	      }
105	      continue;
106	    }
107	    if (line.startsWith("diff --git ")) {
108	      inHeader = true;
109	      const rest = line.slice("diff --git ".length);
110	      if (rest.startsWith('"')) {
111	        const first = readGitPath(rest);
112	        const second = first && first.rest.startsWith(" ") ? first.rest.slice(1) : undefined;
113	        const b = second?.startsWith('"') ? readGitPath(second)?.path : second;
114	        if (!first || b === undefined) {
115	          add(`<unparseable diff header: ${line}>`);
116	          continue;
117	        }
118	        add(diffSidePath(first.path, "a/"));
119	        add(diffSidePath(b, "b/"));
120	      } else {
121	        // Bare: "a/<path> b/<path>". With identical sides the split point is the midpoint; otherwise the
122	        // ---/+++ or rename headers that follow carry the exact paths.
123	        const half = (rest.length - 1) / 2;
124	        if (Number.isInteger(half) && rest[half] === " " && rest.slice(2, half) === rest.slice(half + 3)) {
125	          add(diffSidePath(rest.slice(0, half), "a/"));
126	        } else {
127	          const quotedB = rest.indexOf(' "b/');
128	          const bareB = rest.lastIndexOf(" b/");
129	          const cut = quotedB >= 0 ? quotedB : bareB;
130	          if (cut < 0) {
131	            add(`<unparseable diff header: ${line}>`);
132	            continue;
133	          }
134	          add(diffSidePath(rest.slice(0, cut), "a/"));
135	          const bSide = rest.slice(cut + 1);
136	          add(diffSidePath(bSide.startsWith('"') ? readGitPath(bSide)?.path ?? `<unparseable diff header: ${line}>` : bSide, "b/"));
137	        }
138	      }
139	    } else if (!inHeader) {
140	      continue;
141	    } else if (line.startsWith("--- ")) {
142	      const p = headerPath(line.slice(4));
143	      add(p === undefined ? `<unparseable diff header: ${line}>` : diffSidePath(p, "a/"));
144	    } else if (line.startsWith("+++ ")) {
145	      const p = headerPath(line.slice(4));
146	      add(p === undefined ? `<unparseable diff header: ${line}>` : diffSidePath(p, "b/"));
147	    } else if (line.startsWith("rename from ") || line.startsWith("rename to ")) {
148	      const p = headerPath(line.replace(/^rename (?:from|to) /, ""));
149	      add(p ?? `<unparseable diff header: ${line}>`);
150	    }
151	  }
152	  return Array.from(modified);
153	}
  1	/**
  2	 * `nexus models refresh`: the operator's explicit refresh of the model data. Nothing here runs unless the operator asks;
  3	 * the bundled snapshot is never fetched or modified. The result is written to a local cache that the snapshot reader
  4	 * prefers (see models_snapshot.ts), and every provider passes the same validation as the bundled snapshot.
  5	 * This mirrors scripts/gen_models_snapshot.mjs without the tool-choice clone step: `api.json` carries no tool-choice
  6	 * data, so the reader keeps the bundled snapshot's modes for models the cache lists without them.
  7	 */
  8	import fs from "node:fs";
  9	import os from "node:os";
 10	import path from "node:path";
 11	import { parseSnapshot, type ModelsSnapshot, type ProviderPin, type SnapshotModel, type SnapshotProvider } from "./models_snapshot.js";
 12	
 13	export const MODELS_API_URL = "https://models.dev/api.json";
 14	const MAX_API_BYTES = 30 * 1024 * 1024;
 15	
 16	const OPENAI_CHAT_NPM = new Set([
 17	  "@ai-sdk/openai-compatible", "@ai-sdk/groq", "@ai-sdk/mistral", "@ai-sdk/xai", "@ai-sdk/cerebras",
 18	  "@ai-sdk/togetherai", "@ai-sdk/perplexity", "@ai-sdk/deepinfra", "@openrouter/ai-sdk-provider",
 19	]);
 20	
 21	export function modelsCachePath(home = process.env.HOME || os.homedir()): string {
 22	  return path.join(home, ".cache/nexus/models-snapshot.json");
 23	}
 24	
 25	const protocolClass = (npm: unknown): string =>
 26	  OPENAI_CHAT_NPM.has(String(npm)) ? "openai-chat" : npm === "@ai-sdk/openai" ? "openai-responses" : npm === "@ai-sdk/anthropic" ? "anthropic-messages" : `native:${String(npm)}`;
 27	const num = (v: unknown): number | undefined => (typeof v === "number" && Number.isFinite(v) && v >= 0 ? v : undefined);
 28	const cmp = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 29	
 30	function keepModel(m: any): boolean {
 31	  if (m?.type !== undefined && m.type !== "chat") return false;
 32	  if (m?.tool_call !== true) return false;
 33	  if (m.status === "deprecated" || m.status === "alpha") return false;
 34	  if (typeof m.provider?.api === "string" && !/^https?:/.test(m.provider.api)) return false;
 35	  return typeof m.id === "string";
 36	}
 37	
 38	function buildModel(m: any): SnapshotModel {
 39	  const out: SnapshotModel = { id: m.id, context: num(m.limit?.context) ?? 0, output: num(m.limit?.output) ?? 0, toolCall: true, reasoning: m.reasoning === true };
 40	  const input = num(m.limit?.input);
 41	  if (input !== undefined) out.input = input;
 42	  const effort = (Array.isArray(m.reasoning_options) ? m.reasoning_options : []).find((o: any) => o?.type === "effort" && Array.isArray(o.values))?.values;
 43	  if (Array.isArray(effort) && effort.length && effort.every((v: unknown) => typeof v === "string")) out.effort = [...effort];
 44	  const pin = num(m.cost?.input);
 45	  const pout = num(m.cost?.output);
 46	  if (pin !== undefined && pout !== undefined) out.price = { input: pin, output: pout };
 47	  return out;
 48	}
 49	
 50	/** Convert a models.dev `api.json` document; providers failing validation are dropped and listed in `rejected`. */
 51	export function snapshotFromApi(api: unknown, date: string, pins: Record<string, ProviderPin>): { snapshot: ModelsSnapshot; rejected: string[] } {
 52	  if (!api || typeof api !== "object" || Array.isArray(api)) throw new Error("models.dev data is not an object of providers");
 53	  const providers: SnapshotProvider[] = Object.keys(api).sort(cmp).map((key) => {
 54	    const p = (api as Record<string, any>)[key] ?? {};
 55	    const id = typeof p.id === "string" ? p.id : key;
 56	    const entry: SnapshotProvider = { id, name: p.name, env: Array.isArray(p.env) ? [...p.env] : [], protocol: protocolClass(p.npm), models: [] };
 57	    const pin = Object.hasOwn(pins, id) ? pins[id] : undefined;
 58	    if (typeof p.api === "string" && p.api) entry.baseUrl = p.api;
 59	    else if (pin?.defaultBaseUrl && entry.protocol === "openai-chat") entry.baseUrl = pin.defaultBaseUrl;
 60	    if (entry.baseUrl && (entry.baseUrl.startsWith("${") || (entry.baseUrl.split("://")[1] ?? "").split(/[/?#]/)[0]!.includes("${"))) entry.hostFromEnv = true;
 61	    if (!entry.baseUrl && entry.protocol === "openai-chat") entry.needsBaseUrl = true;
 62	    entry.models = Object.values(p.models ?? {}).filter(keepModel).sort((a: any, b: any) => cmp(a.id, b.id)).map(buildModel);
 63	    return entry;
 64	  });
 65	  return parseSnapshot({ date, license: "MIT", source: MODELS_API_URL, providers }, pins);
 66	}
 67	
 68	export interface RefreshResult {
 69	  file: string;
 70	  date: string;
 71	  providers: number;
 72	  models: number;
 73	  rejected: string[];
 74	}
 75	
 76	/**
 77	 * Fetch models.dev (an explicit operator action), validate, and write the local cache atomically with private
 78	 * permissions. `fetchImpl` is injectable so tests never touch the network.
 79	 */
 80	export async function refreshModelsCache(opts: { pins: Record<string, ProviderPin>; fetchImpl?: typeof fetch; home?: string; now?: Date; signal?: AbortSignal }): Promise<RefreshResult> {
 81	  const doFetch = opts.fetchImpl ?? fetch;
