    29	
    30	export interface ModelsSnapshot {
    31	  date: string;
    32	  commit?: string;
    33	  license: string;
    34	  source: string;
    35	  providers: SnapshotProvider[];
    36	}
    37	
    38	export interface ProviderPin {
    39	  suffixes: string[];
    40	  defaultBaseUrl?: string;
    41	  source: string;
    42	}
    43	
    44	export type ToolChoiceMode = "auto" | "none" | "required" | "tool";
    45	
    46	const ENV_NAME = /^[A-Z0-9][A-Z0-9_]{1,63}$/;
    47	const ENV_DENY = /^AWS_|^GOOGLE_APPLICATION_CREDENTIALS$|_SSH|^GITHUB_TOKEN$/;
    48	const ENV_DENY_ALLOWED = new Set(["amazon-bedrock", "google-vertex", "google-vertex-anthropic", "github-copilot"]);
    49	const LOOPBACK = new Set(["localhost", "127.0.0.1", "[::1]"]);
    50	
    51	const unsafeId = (id: unknown, max: number): boolean =>
    52	  typeof id !== "string" || !id || id.length > max || id.includes("..") || id.startsWith("/") || id.includes("\0");
    53	
    54	/** Reasons a provider entry is refused (empty when it is acceptable). Mirrors scripts/gen_models_snapshot.mjs. */
    55	export function providerViolations(p: SnapshotProvider, pins: Record<string, ProviderPin>): string[] {
    56	  const out: string[] = [];
    57	  if (typeof p?.id !== "string" || !/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(p.id) || p.id.includes("..")) out.push("id");
    58	  if (typeof p?.name !== "string" || !p.name || p.name.length > 200) out.push("name");
    59	  if (typeof p?.protocol !== "string" || !(/^(openai-chat|openai-responses|anthropic-messages)$/.test(p.protocol) || /^native:.{1,200}$/.test(p.protocol))) out.push("protocol");
    60	  const env = Array.isArray(p?.env) ? p.env : [];
    61	  if (!Array.isArray(p?.env)) out.push("env");
    62	  for (const e of env) {
    63	    if (typeof e !== "string" || !ENV_NAME.test(e)) out.push("env name");
    64	    else if (ENV_DENY.test(e) && !ENV_DENY_ALLOWED.has(p.id)) out.push(`env name ${e} not allowed`);
    65	  }
    66	  const pin = Object.hasOwn(pins, p?.id) ? pins[p.id] : undefined;
    67	  if (p?.baseUrl !== undefined) {
    68	    const url = p.baseUrl;
    69	    if (typeof url !== "string" || /[\s\u0000-\u001f]/.test(url)) out.push("baseUrl");
    70	    else {
    71	      for (const m of url.matchAll(/\$\{([^}]*)\}/g)) if (!env.includes(m[1]!)) out.push("baseUrl variable not in env");
    72	      const fromEnv = url.startsWith("${") || (url.split("://")[1] ?? "").split(/[/?#]/)[0]!.includes("${");
    73	      if (fromEnv !== (p.hostFromEnv === true)) out.push("hostFromEnv mismatch");
    74	      if (url.startsWith("${")) {
    75	        if (!/^\$\{[A-Z0-9_]+\}(\/[^$]*)?$/.test(url)) out.push("baseUrl template");
    76	      } else {
    77	        try {
    78	          const u = new URL(url.replace(/\$\{[^}]*\}/g, "placeholder"));
    79	          if (!(u.protocol === "https:" || (u.protocol === "http:" && LOOPBACK.has(u.hostname)))) out.push("baseUrl scheme");
    80	          if (u.username || u.password) out.push("baseUrl credentials");
    81	          if (pin && !fromEnv && !pin.suffixes.some((s) => u.hostname === s || u.hostname.endsWith(`.${s}`))) out.push("baseUrl leaves pinned host");
    82	        } catch {
    83	          out.push("baseUrl does not parse");
    84	        }
    85	      }
    86	    }
    87	  } else if (p?.hostFromEnv !== undefined) out.push("hostFromEnv without baseUrl");
    88	  if (pin && p.hostFromEnv) out.push("pinned provider takes its host from env");
    89	  return out;
    90	}
    91	
    92	/** Keeps only provider entries that pass `providerViolations`; the rest are listed in `rejected`. Never throws. */
    93	export function parseSnapshot(raw: unknown, pins: Record<string, ProviderPin>): { snapshot: ModelsSnapshot; rejected: string[] } {
    94	  const r = (raw ?? {}) as Partial<ModelsSnapshot>;
