    99	    const bad = providerViolations(p, pins);
   100	    if (!bad.length && seen.has(p.id)) bad.push("duplicate");
   101	    if (bad.length) {
   102	      rejected.push(`${String(p?.id).slice(0, 64)}: ${bad.join("; ")}`);
   103	      continue;
   104	    }
   105	    seen.add(p.id);
   106	    providers.push({ ...p, models: (Array.isArray(p.models) ? p.models : []).filter((m) => !unsafeId(m?.id, 200)) });
   107	  }
