   109	    date: typeof r.date === "string" ? r.date : "unknown",
   110	    ...(typeof r.commit === "string" ? { commit: r.commit } : {}),
   111	    license: "MIT",
   112	    source: typeof r.source === "string" ? r.source : "",
   113	    providers,
   114	  };
   115	  return { snapshot, rejected };
   116	}
