  1	/**
  2	 * SI-5 / VC-1: operator-declared boundary rules, checked on a candidate diff by deterministic analysis.
  3	 *
  4	 * The operator declares what must not happen (an import from one layer into another, a change to a protected public
  5	 * file, an import cycle between modules) and which files are public interfaces or schemas. The check reads the unified
  6	 * diff of the candidate and reports:
  7	 *  - violations (the review gate rejects on any),
  8	 *  - advisories (an import outside the declared allow-list, a change that may break an interface or schema, or that
  9	 *    could not be classified),
 10	 *  - coverage: what was analysed, what was skipped and why, and the standing limits of line-based analysis.
 11	 *
 12	 * It reads added and removed lines, not a build: it does not resolve path aliases, re-exports or computed imports, and
 13	 * it sees only what the diff contains. Those limits are part of every report, and an absent rule set means no check at
 14	 * all (`checkBoundaries` returns undefined). Pass the cumulative diff of successive changes to find a breach none of
 15	 * them has alone (an import cycle closed by the second change).
 16	 */
 17	import * as path from "node:path";
 18	import { diffSidePath, extractModifiedFilesFromDiff, headerPath } from "./unified_diff.js";
 19	
 20	export interface ImportRule {
 21	  name: string;
 22	  /** Files the rule applies to (globs, repository-relative). */
 23	  from: string[];
 24	  /** An added import whose target matches any of these is a violation. */
 25	  deny?: string[];
 26	  /** When present, an added import whose target matches none of these (and is not a Node built-in) is an advisory. */
 27	  allow?: string[];
 28	}
 29	
 30	export interface BoundaryRules {
 31	  imports?: ImportRule[];
 32	  /** Files whose change needs the operator's authorisation (`authorizedScope`); otherwise a violation. */
 33	  protected?: string[];
 34	  /** Public interface files: changes are classified compatible / potentially breaking / unknown. */
 35	  interfaces?: string[];
 36	  /** Schema and persistence-format files: classified the same way. */
 37	  schemas?: string[];
 38	  /** Modules (globs) among which no import cycle may exist. */
 39	  acyclic?: string[];
 40	}
 41	
 42	export class BoundaryRulesError extends Error {
 43	  constructor(message: string) {
 44	    super(message);
 45	    this.name = "BoundaryRulesError";
 46	  }
 47	}
 48	
 49	const RULE_KEYS = ["imports", "protected", "interfaces", "schemas", "acyclic"] as const;
 50	const IMPORT_KEYS = ["name", "from", "deny", "allow"] as const;
 51	const MAX_GLOB = 200;
 52	const MAX_ENTRIES = 200;
 53	
 54	function globList(value: unknown, field: string, required = false): string[] | undefined {
 55	  if (value === undefined) {
 56	    if (required) throw new BoundaryRulesError(`${field}: required`);
 57	    return undefined;
 58	  }
 59	  if (!Array.isArray(value) || value.length === 0 || value.length > MAX_ENTRIES) throw new BoundaryRulesError(`${field}: must be a non-empty list of at most ${MAX_ENTRIES} globs`);
 60	  for (const g of value) {
 61	    if (typeof g !== "string" || !g.trim() || g.length > MAX_GLOB || g.includes("\0") || g.startsWith("/") || g.split("/").includes("..")) {
 62	      throw new BoundaryRulesError(`${field}: "${String(g).slice(0, 40)}" is not a repository-relative glob`);
 63	    }
 64	  }
 65	  return value as string[];
 66	}
 67	
 68	/** Strict validation of operator-supplied rules; every error names the field. Unknown keys are refused, not ignored. */
 69	export function parseBoundaryRules(raw: unknown): BoundaryRules {
 70	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new BoundaryRulesError("boundaries: must be an object");
 71	  const r = raw as Record<string, unknown>;
 72	  for (const key of Object.keys(r)) if (!(RULE_KEYS as readonly string[]).includes(key)) throw new BoundaryRulesError(`boundaries.${key}: unknown field (known: ${RULE_KEYS.join(", ")})`);
 73	  const out: BoundaryRules = {};
 74	  if (r.imports !== undefined) {
 75	    if (!Array.isArray(r.imports) || r.imports.length === 0 || r.imports.length > MAX_ENTRIES) throw new BoundaryRulesError(`boundaries.imports: must be a non-empty list of at most ${MAX_ENTRIES} rules`);
 76	    out.imports = r.imports.map((entry, i) => {
 77	      const f = `boundaries.imports[${i}]`;
 78	      if (!entry || typeof entry !== "object" || Array.isArray(entry)) throw new BoundaryRulesError(`${f}: must be an object`);
 79	      const e = entry as Record<string, unknown>;
 80	      for (const key of Object.keys(e)) if (!(IMPORT_KEYS as readonly string[]).includes(key)) throw new BoundaryRulesError(`${f}.${key}: unknown field`);
 81	      if (typeof e.name !== "string" || !/^[\w .:-]{1,80}$/.test(e.name)) throw new BoundaryRulesError(`${f}.name: a short name is required`);
 82	      const deny = globList(e.deny, `${f}.deny`);
 83	      const allow = globList(e.allow, `${f}.allow`);
 84	      if (!deny && !allow) throw new BoundaryRulesError(`${f}: needs deny, allow or both`);
 85	      return { name: e.name, from: globList(e.from, `${f}.from`, true)!, ...(deny ? { deny } : {}), ...(allow ? { allow } : {}) };
 86	    });
 87	  }
 88	  for (const key of ["protected", "interfaces", "schemas", "acyclic"] as const) {
 89	    const list = globList(r[key], `boundaries.${key}`);
 90	    if (list) out[key] = list;
 91	  }
 92	  if (!Object.keys(out).length) throw new BoundaryRulesError("boundaries: declares no rule");
 93	  return out;
 94	}
 95	
 96	// ------------------------------------------------------------------------------------------------ matching
 97	
 98	/** `**` crosses directories, `*` and `?` do not. Case-sensitive. */
 99	function globToRegExp(glob: string): RegExp {
100	  let out = "";
101	  for (let i = 0; i < glob.length; i++) {
102	    const ch = glob[i];
103	    if (ch === "*") {
104	      if (glob[i + 1] === "*") {
105	        if (glob[i + 2] === "/") {
106	          out += "(?:.*/)?";
107	          i += 2;
108	        } else {
109	          out += ".*";
110	          i++;
111	        }
112	      } else out += "[^/]*";
113	    } else if (ch === "?") out += "[^/]";
114	    else out += ch.replace(/[.+^${}()|[\]\\]/g, "\\$&");
115	  }
116	  return new RegExp(`^${out}$`);
117	}
118	
119	const SOURCE_EXT = /\.(?:[cm]?[jt]sx?|py|rs|go)$/;
120	const stripSourceExt = (p: string): string => p.replace(SOURCE_EXT, "").replace(/\/index$/, "");
121	
122	/** Whether `target` (a file path or a module path, extension optional) matches a glob; an extension in the glob is ignored so `src/db/client.ts` also names the import `../db/client`. */
123	function matches(glob: string, target: string): boolean {
124	  const re = globToRegExp(glob);
125	  if (re.test(target)) return true;
126	  const bare = stripSourceExt(target);
127	  return re.test(bare) || globToRegExp(stripSourceExt(glob)).test(bare);
128	}
129	
130	const anyMatch = (globs: readonly string[] | undefined, target: string): boolean => Boolean(globs?.some((g) => matches(g, target)));
131	
132	// ------------------------------------------------------------------------------------------------ diff
133	
134	export interface FileChange {
135	  path: string;
136	  status: "added" | "deleted" | "modified";
137	  added: string[];
138	  removed: string[];
139	}
140	
141	/**
142	 * Per-file added and removed lines of a unified diff. Hunk bodies are consumed by the counts in their `@@` header, so a
143	 * removed line that reads "-- note" or an added "++ note" is content, never a file header. A file whose header cannot be
144	 * read is listed in `unparsed` and not analysed.
145	 */
146	export function parseDiffFiles(diff: string): { files: FileChange[]; unparsed: string[] } {
147	  const files: FileChange[] = [];
148	  const unparsed: string[] = [];
149	  const lines = diff.split("\n");
150	  let current: FileChange | undefined;
151	  let oldLeft = 0;
152	  let newLeft = 0;
153	  for (let i = 0; i < lines.length; i++) {
154	    const line = lines[i];
155	    if (oldLeft > 0 || newLeft > 0) {
156	      if (line.startsWith("--- ") && lines[i + 1]?.startsWith("+++ ") && lines[i + 2]?.startsWith("@@")) {
157	        oldLeft = 0;
158	        newLeft = 0;
159	      } else if (line.startsWith("\\")) continue;
160	      else if (line.startsWith("+") && newLeft > 0) {
161	        current?.added.push(line.slice(1));
162	        newLeft--;
163	        continue;
164	      } else if (line.startsWith("-") && oldLeft > 0) {
165	        current?.removed.push(line.slice(1));
166	        oldLeft--;
167	        continue;
168	      } else if (line.startsWith(" ") || line === "") {
169	        oldLeft = Math.max(0, oldLeft - 1);
170	        newLeft = Math.max(0, newLeft - 1);
171	        continue;
172	      } else {
173	        oldLeft = 0;
174	        newLeft = 0;
175	      }
176	    }
177	    if (line.startsWith("--- ") && lines[i + 1]?.startsWith("+++ ")) {
178	      const from = headerPath(line.slice(4));
179	      const to = headerPath(lines[i + 1].slice(4));
180	      const a = from === undefined ? undefined : diffSidePath(from, "a/");
181	      const b = to === undefined ? undefined : diffSidePath(to, "b/");
182	      const name = b ?? a;
183	      if (name === undefined) {
184	        unparsed.push(`<unreadable file header: ${line.slice(0, 60)}>`);
185	        current = undefined;
186	      } else {
187	        current = { path: name, status: a === undefined ? "added" : b === undefined ? "deleted" : "modified", added: [], removed: [] };
188	        files.push(current);
189	      }
190	      i++;
191	      continue;
192	    }
193	    if (line.startsWith("@@")) {
194	      const counts = /^@@ -\d+(?:,(\d+))? \+\d+(?:,(\d+))? @@/.exec(line);
195	      if (counts) {
196	        oldLeft = counts[1] === undefined ? 1 : Number(counts[1]);
197	        newLeft = counts[2] === undefined ? 1 : Number(counts[2]);
198	      }
199	    }
200	  }
201	  return { files, unparsed };
202	}
203	
204	// ------------------------------------------------------------------------------------------------ imports
205	
206	type Language = "js" | "py" | "rs" | "go";
207	const LANGUAGE_BY_EXT: Record<string, Language> = { ".ts": "js", ".tsx": "js", ".js": "js", ".jsx": "js", ".mjs": "js", ".cjs": "js", ".mts": "js", ".cts": "js", ".py": "py", ".rs": "rs", ".go": "go" };
208	const languageOf = (file: string): Language | undefined => LANGUAGE_BY_EXT[path.posix.extname(file).toLowerCase()];
209	
210	interface ImportRef {
211	  spec: string;
212	  /** A specifier the analysis cannot read (a computed dynamic import). */
213	  computed?: true;
214	}
215	
216	/** The import(s) one added line makes, by language. A line is read alone: no multi-line import continuation is followed. */
217	export function importsOnLine(line: string, language: Language): ImportRef[] {
218	  const found: ImportRef[] = [];
219	  if (language === "js") {
220	    const statement = /^\s*(?:import|export)\s+(?:type\s+)?(?:[\w*${},\s]+?\s+from\s+)?["']([^"']+)["']/.exec(line);
221	    if (statement) found.push({ spec: statement[1] });
222	    for (const m of line.matchAll(/\brequire\(\s*["']([^"']+)["']\s*\)/g)) found.push({ spec: m[1] });
223	    for (const m of line.matchAll(/\bimport\(\s*(["'][^"']+["']|[^)]*)\)/g)) {
224	      const literal = /^["']([^"']+)["']$/.exec(m[1].trim());
225	      found.push(literal ? { spec: literal[1] } : { spec: "", computed: true });
226	    }
227	  } else if (language === "py") {
228	    const from = /^\s*from\s+(\.*[\w.]*)\s+import\b/.exec(line);
229	    if (from) found.push({ spec: from[1] });
230	    else {
231	      const plain = /^\s*import\s+([\w.]+(?:\s*,\s*[\w.]+)*)/.exec(line);
232	      if (plain) for (const part of plain[1].split(",")) found.push({ spec: part.trim() });
233	    }
234	  } else if (language === "rs") {
235	    const use = /^\s*(?:pub(?:\([^)]*\))?\s+)?use\s+([\w:]+)/.exec(line);
236	    if (use) found.push({ spec: use[1] });
237	  } else {
238	    const go = /^\s*import\s+(?:[\w.]+\s+)?"([^"]+)"/.exec(line);
239	    if (go) found.push({ spec: go[1] });
240	  }
241	  return found;
242	}
243	
244	/** The target an import names, in the form rules are matched against: a repository path (extensionless) for a relative import, otherwise the specifier as written. */
245	export function resolveImportTarget(fromFile: string, spec: string, language: Language): string {
246	  if (language === "js") {
247	    if (!spec.startsWith(".")) return spec;
248	    return stripSourceExt(path.posix.normalize(path.posix.join(path.posix.dirname(fromFile), spec)));
249	  }
250	  if (language === "py") {
251	    const dots = /^\.*/.exec(spec)![0].length;
252	    const rest = spec.slice(dots).replace(/\./g, "/");
253	    if (!dots) return rest;
254	    const base = path.posix.dirname(fromFile).split("/").slice(0, Math.max(0, path.posix.dirname(fromFile).split("/").length - (dots - 1))).join("/");
255	    return path.posix.normalize(path.posix.join(base || ".", rest)).replace(/^\.$/, "");
256	  }
257	  return spec;
258	}
259	
260	const isNodeBuiltin = (target: string): boolean => target.startsWith("node:");
261	
262	// ------------------------------------------------------------------------------------------------ classification
263	
264	export type ChangeClass = "compatible" | "potentially_breaking" | "unknown";
265	export interface ChangeClassification {
266	  path: string;
267	  kind: "interface" | "schema";
268	  class: ChangeClass;
269	  reason: string;
270	}
271	
272	const PUBLIC_DECLARATIONS: Record<Language, RegExp[]> = {
273	  js: [/^\s*export\s+(?:default\s+)?(?:declare\s+)?(?:abstract\s+)?(?:async\s+)?(?:function\*?|class|const|let|var|interface|type|enum|namespace)\s+([\w$]+)/, /^\s*export\s+\{([^}]*)\}/],
274	  rs: [/^\s*pub(?:\([^)]*\))?\s+(?:async\s+)?(?:unsafe\s+)?(?:fn|struct|enum|trait|const|static|type|mod|union)\s+(\w+)/],
275	  go: [/^func\s+(?:\([^)]*\)\s*)?([A-Z]\w*)/, /^type\s+([A-Z]\w*)/, /^(?:var|const)\s+([A-Z]\w*)/],
276	  py: [/^(?:async\s+)?def\s+([A-Za-z]\w*)/, /^class\s+([A-Za-z]\w*)/],
277	};
278	
279	function publicSymbols(lines: string[], language: Language): Map<string, string> {
280	  const symbols = new Map<string, string>();
281	  for (const line of lines) {
282	    for (const re of PUBLIC_DECLARATIONS[language]) {
283	      const m = re.exec(line);
284	      if (!m) continue;
285	      const names = re === PUBLIC_DECLARATIONS.js[1] ? m[1].split(",").map((s) => s.trim().split(/\s+as\s+/).pop()!).filter(Boolean) : [m[1]];
286	      for (const name of names) symbols.set(name, line.trim());
287	    }
288	  }
289	  return symbols;
290	}
291	
292	function classifyInterface(change: FileChange): { class: ChangeClass; reason: string } {
293	  const language = languageOf(change.path);
294	  if (!language) return { class: "unknown", reason: "no declaration analysis for this file type" };
295	  if (change.status === "deleted") return { class: "potentially_breaking", reason: "the file was deleted" };
296	  const before = publicSymbols(change.removed, language);
297	  const after = publicSymbols(change.added, language);
298	  const removed = [...before.keys()].filter((name) => !after.has(name));
299	  const changed = [...before.keys()].filter((name) => after.has(name) && after.get(name) !== before.get(name));
300	  if (removed.length) return { class: "potentially_breaking", reason: `public declaration(s) removed: ${removed.slice(0, 5).join(", ")}` };
301	  if (changed.length) return { class: "potentially_breaking", reason: `public declaration(s) changed: ${changed.slice(0, 5).join(", ")}` };
302	  const addedOnly = [...after.keys()].filter((name) => !before.has(name));
303	  return { class: "compatible", reason: addedOnly.length ? `public declaration(s) added: ${addedOnly.slice(0, 5).join(", ")}` : "no public declaration was removed or changed (only top-level declarations are read)" };
304	}
305	
306	function classifySchema(change: FileChange): { class: ChangeClass; reason: string } {
307	  if (change.status === "deleted") return { class: "potentially_breaking", reason: "the schema file was deleted" };
308	  const ext = path.posix.extname(change.path).toLowerCase();
309	  const removed = change.removed.join("\n");
310	  const added = change.added.join("\n");
311	  if (ext === ".sql") {
312	    if (/\b(?:DROP|RENAME)\b|\bALTER\s+(?:TABLE\s+\S+\s+)?(?:ALTER\s+)?COLUMN\b[^;]*\bTYPE\b|\bNOT\s+NULL\b/i.test(added) || removed.trim()) return { class: "potentially_breaking", reason: "a migration drops, renames, retypes or tightens a column, or removes a statement" };
313	    return { class: "compatible", reason: "only additive statements" };
314	  }
315	  if (ext === ".proto") {
316	    const field = (text: string) => new Set([...text.matchAll(/^\s*(?:repeated\s+|optional\s+)?[\w.]+\s+(\w+)\s*=\s*(\d+)/gm)].map((m) => `${m[1]}=${m[2]}`));
317	    const was = field(removed);
318	    const now = field(added);
319	    const gone = [...was].filter((f) => !now.has(f));
320	    return gone.length ? { class: "potentially_breaking", reason: `field(s) removed or renumbered: ${gone.slice(0, 5).join(", ")}` } : { class: "compatible", reason: "no field was removed or renumbered" };
321	  }
322	  if (ext === ".json" || ext === ".yaml" || ext === ".yml") {
323	    if (!change.removed.length) return { class: "compatible", reason: "only additions" };
324	    const keys = (text: string) => new Set([...text.matchAll(/["']?([\w$-]+)["']?\s*:/g)].map((m) => m[1]));
325	    const was = keys(removed);
326	    const now = keys(added);
327	    const gone = [...was].filter((k) => !now.has(k));
328	    if (gone.length || /"required"|"type"|required:|type:/.test(removed)) return { class: "potentially_breaking", reason: gone.length ? `key(s) removed: ${gone.slice(0, 5).join(", ")}` : "a type or required constraint line changed" };
329	    return { class: "unknown", reason: "lines were rewritten; only a value changed or the change is not a key removal, so compatibility is not decided" };
330	  }
331	  return change.removed.length ? { class: "unknown", reason: "no analysis for this file type and lines were removed" } : { class: "compatible", reason: "only additions" };
332	}
333	
334	// ------------------------------------------------------------------------------------------------ the check
335	
336	export interface BoundaryFinding {
337	  rule: string;
338	  path: string;
339	  detail: string;
340	}
341	
342	export interface BoundaryReport {
343	  violations: BoundaryFinding[];
344	  advisories: BoundaryFinding[];
345	  classifications: ChangeClassification[];
346	  coverage: {
347	    filesInDiff: number;
348	    analysed: number;
349	    skipped: Array<{ path: string; reason: string }>;
350	    /** Standing limits plus anything specific to this diff (omitted sections, computed imports). */
351	    limits: string[];
352	  };
353	}
354	
355	const STANDING_LIMITS = [
356	  "Analysis reads the lines the diff adds and removes, not a build: path aliases, re-exports and computed imports are not resolved.",
357	  "An import written across several lines is read only where its `from` clause is on the line the diff adds.",
358	  "Interface classification reads top-level declarations only; a change inside a declaration's body is not seen.",
359	  "Rust imports are matched as module paths (for example crate::db::x), Python imports as dotted paths turned into directories, Go imports as written; none are mapped to files.",
360	  "Import cycles are found among the imports this diff adds; a cycle that needs an import already in the repository is not found unless that import is in the diff.",
361	];
362	
363	const OMISSION_NOTE = /^\[(\d+) (?:protected file section\(s\)|new file\(s\)|untracked nested git repositor(?:y|ies)) omitted[^\]]*\]$/;
364	
365	export function checkBoundaries(diff: string, rules: BoundaryRules | undefined, context: { authorizedScope?: readonly string[] } = {}): BoundaryReport | undefined {
366	  if (!rules) return undefined;
367	  const violations: BoundaryFinding[] = [];
368	  const advisories: BoundaryFinding[] = [];
369	  const classifications: ChangeClassification[] = [];
370	  const skipped: Array<{ path: string; reason: string }> = [];
371	  const limits = [...STANDING_LIMITS];
372	  const parsed = parseDiffFiles(diff);
373	  for (const bad of parsed.unparsed) skipped.push({ path: bad, reason: "file header could not be read" });
374	  for (const line of diff.split("\n")) if (OMISSION_NOTE.test(line.trim())) limits.push(`Not analysed (hidden from this diff): ${line.trim().slice(1, -1)}.`);
375	  const touched = new Set([...extractModifiedFilesFromDiff(diff), ...parsed.files.map((f) => f.path)]);
376	  let analysed = 0;
377	
378	  for (const file of touched) {
379	    if (file.startsWith("<unparseable")) {
380	      violations.push({ rule: "diff", path: file, detail: "a file header in the diff could not be read, so the boundary check cannot vouch for the change" });
381	      continue;
382	    }
383	    if (rules.protected && anyMatch(rules.protected, file) && !(context.authorizedScope ?? []).some((a) => a === "*" || file === a || file.startsWith(`${a}/`))) {
384	      violations.push({ rule: "protected", path: file, detail: "a protected public file changed without being in the authorised scope" });
385	    }
386	  }
387	
388	  const computedImports: string[] = [];
389	  const edges = new Map<string, Set<string>>();
390	  for (const change of parsed.files) {
391	    const language = languageOf(change.path);
392	    let importsRead = false;
393	    if (language && (rules.imports || rules.acyclic)) {
394	      const fromModule = stripSourceExt(change.path);
395	      for (const line of change.added) {
396	        for (const ref of importsOnLine(line, language)) {
397	          importsRead = true;
398	          if (ref.computed) {
399	            computedImports.push(change.path);
400	            continue;
401	          }
402	          const target = resolveImportTarget(change.path, ref.spec, language);
403	          for (const rule of rules.imports ?? []) {
404	            if (!anyMatch(rule.from, change.path)) continue;
405	            if (rule.deny && anyMatch(rule.deny, target)) violations.push({ rule: rule.name, path: change.path, detail: `imports ${target}, which this rule denies` });
406	            else if (rule.allow && !anyMatch(rule.allow, target) && !isNodeBuiltin(target)) advisories.push({ rule: rule.name, path: change.path, detail: `imports ${target}, outside the declared allow-list (an undeclared dependency)` });
407	          }
408	          if (rules.acyclic && anyMatch(rules.acyclic, change.path) && anyMatch(rules.acyclic, target) && target !== fromModule) {
409	            (edges.get(fromModule) ?? edges.set(fromModule, new Set()).get(fromModule)!).add(target);
410	          }
411	        }
412	      }
413	    }
414	    const isInterface = Boolean(rules.interfaces && anyMatch(rules.interfaces, change.path));
415	    const isSchema = Boolean(rules.schemas && anyMatch(rules.schemas, change.path));
416	    if (isInterface) classifications.push({ path: change.path, kind: "interface", ...classifyInterface(change) });
417	    if (isSchema) classifications.push({ path: change.path, kind: "schema", ...classifySchema(change) });
418	    if (importsRead || isInterface || isSchema || (language && (rules.imports || rules.acyclic))) analysed++;
419	    else if (rules.imports || rules.acyclic) skipped.push({ path: change.path, reason: "file type is not analysed for imports" });
420	  }
421	  if (computedImports.length) limits.push(`Computed dynamic imports (not resolvable) in: ${[...new Set(computedImports)].slice(0, 5).join(", ")}.`);
422	
423	  const cycle = rules.acyclic ? findCycle(edges) : undefined;
424	  if (cycle) violations.push({ rule: "acyclic", path: cycle[0], detail: `import cycle among the diff's imports: ${cycle.join(" -> ")}` });
425	
426	  for (const c of classifications) {
427	    if (c.class === "compatible") continue;
428	    advisories.push({ rule: c.kind, path: c.path, detail: c.class === "potentially_breaking" ? `potentially breaking ${c.kind} change: ${c.reason}` : `${c.kind} change could not be classified: ${c.reason}` });
429	  }
430	  return { violations, advisories, classifications, coverage: { filesInDiff: touched.size, analysed, skipped, limits } };
431	}
432	
433	/** One import cycle in the edge map, as a closed path (`a -> b -> a`), or undefined. */
434	function findCycle(edges: Map<string, Set<string>>): string[] | undefined {
435	  const state = new Map<string, 1 | 2>();
436	  const stack: string[] = [];
437	  const visit = (node: string): string[] | undefined => {
438	    state.set(node, 1);
439	    stack.push(node);
440	    for (const next of edges.get(node) ?? []) {
441	      if (state.get(next) === 1) return [...stack.slice(stack.indexOf(next)), next];
442	      if (!state.has(next)) {
443	        const found = visit(next);
444	        if (found) return found;
445	      }
446	    }
447	    stack.pop();
448	    state.set(node, 2);
449	    return undefined;
450	  };
451	  for (const node of edges.keys()) if (!state.has(node)) {
452	    const found = visit(node);
453	    if (found) return found;
454	  }
455	  return undefined;
456	}
457	
458	/** One line per finding, for a reviewer prompt or a verdict note. */
459	export function describeBoundaryReport(report: BoundaryReport): string[] {
460	  return [
461	    ...report.violations.map((f) => `VIOLATION [${f.rule}] ${f.path}: ${f.detail}`),
462	    ...report.advisories.map((f) => `advisory [${f.rule}] ${f.path}: ${f.detail}`),
463	  ];
464	}

