 96	// ------------------------------------------------------------------------------------------------ matching
 97	
 98	/** `**` crosses directories, `*` and `?` do not. Case-sensitive. */
 99	function globToRegExp(glob: string): RegExp {
100	  let out = "";
101	  for (let i = 0; i < glob.length; i++) {
102	    const ch = glob[i];
103	    if (ch === "*") {
104	      if (glob[i + 1] === "*") {
105	        if (glob[i + 2] === "/") {
106	          out += "(?:.*/)?";
107	          i += 2;
108	        } else {
109	          out += ".*";
110	          i++;
111	        }
112	      } else out += "[^/]*";
113	    } else if (ch === "?") out += "[^/]";
114	    else out += ch.replace(/[.+^${}()|[\]\\]/g, "\\$&");
115	  }
116	  return new RegExp(`^${out}$`);
117	}
118	
119	const SOURCE_EXT = /\.(?:[cm]?[jt]sx?|py|rs|go)$/;
120	const stripSourceExt = (p: string): string => p.replace(SOURCE_EXT, "").replace(/\/index$/, "");
121	
122	/** Whether `target` (a file path or a module path, extension optional) matches a glob; an extension in the glob is ignored so `src/db/client.ts` also names the import `../db/client`. */
123	function matches(glob: string, target: string): boolean {
124	  const re = globToRegExp(glob);
125	  if (re.test(target)) return true;
126	  const bare = stripSourceExt(target);
127	  return re.test(bare) || globToRegExp(stripSourceExt(glob)).test(bare);
128	}
129	
130	const anyMatch = (globs: readonly string[] | undefined, target: string): boolean => Boolean(globs?.some((g) => matches(g, target)));
131	
132	// ------------------------------------------------------------------------------------------------ diff
133	
134	export interface FileChange {
135	  path: string;
136	  status: "added" | "deleted" | "modified";
137	  added: string[];
138	  removed: string[];
139	}
140	
141	/**
142	 * Per-file added and removed lines of a unified diff. Hunk bodies are consumed by the counts in their `@@` header, so a
143	 * removed line that reads "-- note" or an added "++ note" is content, never a file header. A file whose header cannot be
144	 * read is listed in `unparsed` and not analysed.
145	 */
146	export function parseDiffFiles(diff: string): { files: FileChange[]; unparsed: string[] } {
147	  const files: FileChange[] = [];
148	  const unparsed: string[] = [];
149	  const lines = diff.split("\n");
150	  let current: FileChange | undefined;
151	  let oldLeft = 0;
152	  let newLeft = 0;
153	  for (let i = 0; i < lines.length; i++) {
154	    const line = lines[i];
155	    if (oldLeft > 0 || newLeft > 0) {
156	      if (line.startsWith("--- ") && lines[i + 1]?.startsWith("+++ ") && lines[i + 2]?.startsWith("@@")) {
157	        oldLeft = 0;
158	        newLeft = 0;
159	      } else if (line.startsWith("\\")) continue;
160	      else if (line.startsWith("+") && newLeft > 0) {
161	        current?.added.push(line.slice(1));
162	        newLeft--;
163	        continue;
164	      } else if (line.startsWith("-") && oldLeft > 0) {
165	        current?.removed.push(line.slice(1));
166	        oldLeft--;
167	        continue;
168	      } else if (line.startsWith(" ") || line === "") {
169	        oldLeft = Math.max(0, oldLeft - 1);
170	        newLeft = Math.max(0, newLeft - 1);
171	        continue;
172	      } else {
173	        oldLeft = 0;
174	        newLeft = 0;
175	      }
176	    }
177	    if (line.startsWith("--- ") && lines[i + 1]?.startsWith("+++ ")) {
178	      const from = headerPath(line.slice(4));
179	      const to = headerPath(lines[i + 1].slice(4));
180	      const a = from === undefined ? undefined : diffSidePath(from, "a/");
181	      const b = to === undefined ? undefined : diffSidePath(to, "b/");
182	      const name = b ?? a;
183	      if (name === undefined) {
184	        unparsed.push(`<unreadable file header: ${line.slice(0, 60)}>`);
185	        current = undefined;
186	      } else {
187	        current = { path: name, status: a === undefined ? "added" : b === undefined ? "deleted" : "modified", added: [], removed: [] };
188	        files.push(current);
189	      }
190	      i++;
191	      continue;
192	    }
193	    if (line.startsWith("@@")) {
194	      const counts = /^@@ -\d+(?:,(\d+))? \+\d+(?:,(\d+))? @@/.exec(line);
195	      if (counts) {
196	        oldLeft = counts[1] === undefined ? 1 : Number(counts[1]);
197	        newLeft = counts[2] === undefined ? 1 : Number(counts[2]);
198	      }
199	    }
200	  }
201	  return { files, unparsed };
202	}
