 13	/** Chat Completions usage (OpenRouter adds `cost`). */
 14	export function chatUsage(u: any): UsageReport | undefined {
 15	  if (!u || typeof u !== "object") return undefined;
 16	  const r: UsageReport = {};
 17	  if (num(u.prompt_tokens) !== undefined) r.inputTokens = u.prompt_tokens;
 18	  if (num(u.completion_tokens) !== undefined) r.outputTokens = u.completion_tokens;
 19	  if (num(u.prompt_tokens_details?.cached_tokens) !== undefined) r.cachedInputTokens = u.prompt_tokens_details.cached_tokens;
 20	  if (num(u.completion_tokens_details?.reasoning_tokens) !== undefined) r.reasoningTokens = u.completion_tokens_details.reasoning_tokens;
