 25	export function buildChatRequest(input: NativeRequestInput): NativeRequest {
 26	  const opts = input.chat ?? { toolChoice: "auto", capOutput: false, usage: "native" };
 27	  const body: Record<string, unknown> = {
 28	    model: input.model,
 29	    messages: input.messages.map((m) => ({
 30	      role: m.role,
 31	      content: m.content ?? null,
 32	      ...(m.tool_calls ? { tool_calls: m.tool_calls } : {}),
 33	      ...(m.tool_call_id ? { tool_call_id: m.tool_call_id } : {}),
 34	      ...(m.name ? { name: m.name } : {}),
 35	    })),
 36	    temperature: input.temperature,
 37	  };
 38	  if (input.stream) body.stream = true;
 39	  // A streamed request sets its output cap after the tools; a plain one before them.
 40	  if (!input.stream && opts.capOutput) body.max_tokens = input.maxOutputTokens;
 41	  if (input.tools.length > 0) {
 42	    body.tools = input.tools;
 43	    body.tool_choice = opts.toolChoice;
 44	  }
 45	  if (input.stream && opts.capOutput) body.max_tokens = input.maxOutputTokens;
 46	  if (opts.usage === "openrouter") body.usage = { include: true };
 47	  if (input.stream && (opts.usage === "openrouter" || opts.usage === "stream-options")) body.stream_options = { include_usage: true };
