  public getContextBudget(): TokenBudget {
    const limit = this.contextLimit();
    return calculateContextBudget(this.messages, this.getEffectiveTools(), limit);
  }

  /**
   * What admission keeps free beside the prompt: the output allowance (advertised by the provider, set by the operator,
   * or the client default, see provider_capabilities.ts) and the tool-output headroom, a scheduling policy for the next
   * tool results (min(4096, context/8) unless configured). Neither is a measurement.
   */
  private getContextReserves(): { completion: number; toolResponse: number; total: number } {
    const limits = this.effectiveLimits();
    const completion = limits.outputAllowance;
    const toolResponse = toolHeadroomPolicy(limits.contextLimit, this.config.toolResponseReserveTokens);
    return { completion, toolResponse, total: completion + toolResponse };
  }

  /** The selected model's context and output limits from the models.dev data, for cloud providers only (never the appliance). */
  private referenceLimits(): { context?: number; output?: number } | undefined {
  advertised: Advertisement | undefined,
  operatorContext?: number,
  operatorOutput?: number,
  /** The bundled or refreshed model data (models.dev): below advertised capacity and the operator's setting, above the client default. */
  reference?: { context?: number; output?: number },
): Pick<ProviderCapabilities, "contextLimit" | "contextSource" | "outputAllowance" | "outputSource"> {
  const adCtx = typeof advertised?.contextLength === "number" ? advertised.contextLength : undefined;
  let contextLimit: number;
  let contextSource: SizingSource;
  if (adCtx !== undefined && operatorContext !== undefined) {
    contextLimit = Math.min(adCtx, operatorContext);
    contextSource = operatorContext <= adCtx ? "operator" : "operator_capped_by_advertised";
  } else if (adCtx !== undefined) {
    contextLimit = adCtx;
    contextSource = "advertised";
  } else if (operatorContext !== undefined) {
    contextLimit = operatorContext;
    contextSource = "operator";
  } else if (reference?.context && reference.context > 0) {
    contextLimit = reference.context;
    contextSource = "snapshot";
  } else {
    contextLimit = CLIENT_DEFAULT_CONTEXT;
    contextSource = "client_default";
  }
  const adOut = advertised?.maxCompletionTokens;
  let outputAllowance: number;
  let outputSource: SizingSource;
  if (adOut !== undefined && operatorOutput !== undefined) {
    outputAllowance = Math.min(adOut, operatorOutput);
    outputSource = operatorOutput <= adOut ? "operator" : "operator_capped_by_advertised";
  } else if (adOut !== undefined) {
    outputAllowance = adOut;
    outputSource = "advertised";
  } else if (operatorOutput !== undefined) {
    outputAllowance = operatorOutput;
    outputSource = "operator";
  } else if (reference?.output && reference.output > 0) {
    outputAllowance = reference.output;
    outputSource = "snapshot";
  } else {
    outputAllowance = Math.min(CLIENT_DEFAULT_OUTPUT, Math.floor(contextLimit / 4));
    outputSource = "client_default";
  }
  // An output allowance can never take the whole window.
  outputAllowance = Math.max(1, Math.min(outputAllowance, Math.floor(contextLimit / 2)));
  return { contextLimit, contextSource, outputAllowance, outputSource };
}

